// generar_308_linea_tiempo_momentos_perfil.js
// CHIQUI Entre Señales — Línea de tiempo de momentos en el Perfil
//
// Los momentos de vida dejan de acumularse en el registro diario y pasan
// a tener su propia LÍNEA DE TIEMPO en el Perfil de la mascota.
//
// EN EL REGISTRO DIARIO:
//   · Los momentos ÚNICOS (no repetibles) desaparecen del selector una
//     vez registrados: el día que llegó a casa, esterilización, primer
//     viaje y conoció el mar. Los repetibles (mudanza, nuevo integrante,
//     nuevo compañero, superó enfermedad, despedida, otro) se mantienen.
//   · Los cambios de edad (primeras canas, ojos opacos) ya desaparecían
//     al registrarse (siguen igual).
//   · Se quita del registro diario la lista "Ya registrados" (esa línea
//     de tiempo ahora vive en el Perfil).
//
// EN EL PERFIL (nueva sección desplegable "Momentos de su vida",
// ubicada entre Recordatorios y Mi cuenta):
//   Una línea de tiempo agrupada en tres bloques:
//     🍼 Hitos de bebé      (tabla hitos_cachorro)
//     💛 Momentos de vida   (momentos normales)
//     🍂 Cambios de la edad (canas, ojos opacos)
//   Cada uno ordenado del más reciente al más antiguo, con su fecha.
//
// Archivos:
//   · components/LineaTiempoMomentos.tsx  (nuevo)
//   · app/perfil/page.tsx                 (integra el componente)
//   · app/registro-diario/page.tsx        (oculta únicos + quita lista)
//
// No hay SQL (usa las tablas hitos_cachorro y momentos que ya existen).
//
// Uso:
//   node generar_308_linea_tiempo_momentos_perfil.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "components/LineaTiempoMomentos.tsx",
    base64: ""
  },
  {
    ruta: "app/perfil/page.tsx",
    base64: ""
  },
  {
    ruta: "app/registro-diario/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 3 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
